      message: `Письмо отправлено на ${email}`,
      variant: 'success',
    });
    setEmail('');
  };

  return (
    <form
      onSubmit={submit}
      style={{ display: 'flex', gap: '8px', alignItems: 'flex-end' }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
